import {translationLinks} from './i18n.js?v=6';
// Extended cases reuse the quiz engine while keeping the shared assumptions available.
export function createCaseLibrary({pb,getStore,start,byId}) {
 const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const $=s=>document.querySelector(s), cases=pb.cases, caseById=Object.fromEntries(cases.map(c=>[c.id,c])), sources=Object.fromEntries(pb.sources.map(s=>[s.id,s]));
 let filters={theme:'all',status:'all',search:''}, briefOpen=true;
 const validResult=id=>getStore().answers[id]&&!getStore().answers[id].needsReview;
 const attempted=c=>c.questionIds.filter(validResult).length;
 const correct=c=>c.questionIds.filter(id=>validResult(id)&&getStore().answers[id].correct).length;
 const needsReview=c=>c.questionIds.some(id=>getStore().answers[id]&&(!getStore().answers[id].correct||getStore().answers[id].needsReview));
 const matching=()=>cases.filter(c=>(filters.theme==='all'||c.theme===filters.theme)&&(filters.status==='all'||filters.status==='new'&&attempted(c)<c.questionIds.length||filters.status==='review'&&needsReview(c)||filters.status==='complete'&&attempted(c)===c.questionIds.length)&&(!filters.search||[c.title,c.context,...c.objectives,...c.questionIds.map(id=>byId[id].prompt)].join(' ').toLowerCase().includes(filters.search.toLowerCase())));
 const sourceLinks=c=>c.sourceIds.map(id=>sources[id]).filter(Boolean).map(s=>`<a href="${E(s.url)}" target="_blank" rel="noopener noreferrer">${E(s.title)} ↗ <span>${E(s.date)}</span></a>`).join('');
 function cards(){return matching().map(c=>`<article class="pb-card"><div class="pb-card-top"><span class="tag">CASE ${E(c.id.slice(2))}</span><span class="small">${E(c.theme)}</span></div><h2>${E(c.title)}</h2><p>${E(c.context)}</p><div class="pb-objectives">${c.objectives.map(o=>`<span>${E(o)}</span>`).join('')}</div><div class="pb-card-bottom"><span>${c.questionIds.length} MCQ parts · 6 options each<br><span class="small">${attempted(c)} attempted · ${correct(c)} correct · about ${c.estimatedMinutes||35} minutes</span></span><button class="primary" data-start-case="${E(c.id)}">Open case →</button></div><div class="bar"><i style="width:${attempted(c)/c.questionIds.length*100}%"></i></div></article>`).join('')||'<p class="empty">No cases match. Try a different topic or review queue.</p>'}
 function lobby(){filters={theme:'all',status:'all',search:''};const qs=pb.questions,s=getStore().session,done=qs.filter(q=>validResult(q.id)),right=done.filter(q=>getStore().answers[q.id].correct);return `<p class="eyebrow">PB20 · EXTENDED CASE STUDIES</p><h1>Follow one story.<br>Work through every mechanism.</h1><p class="intro">20 long questions, each with eight connected MCQ parts. Work from the setup through changing assumptions and edge cases, at IB400 Exam, Challenge and S&T100 difficulty.</p><div class="stats-row"><div class="stat"><strong>${cases.filter(c=>attempted(c)===c.questionIds.length).length}<small class="small"> / ${cases.length}</small></strong><span>CASES COMPLETED</span></div><div class="stat"><strong>${done.length}<small class="small"> / ${qs.length}</small></strong><span>PARTS ATTEMPTED</span></div><div class="stat"><strong>${done.length?Math.round(right.length/done.length*100):0}%</strong><span>LATEST ANSWER ACCURACY</span></div><div class="stat"><strong>${cases.filter(needsReview).length}</strong><span>CASES TO REVISIT</span></div></div><div class="note">Public events set the scene. All numbers, preferences and economic shocks are hypothetical teaching assumptions. You are assessed only on EC2102 concepts. Each part states the scenario it uses, and the shared case brief stays available throughout.</div><div class="filter-panel pb-filters"><label>Context<select id="pb-theme"><option value="all">All contexts</option>${[...new Set(cases.map(c=>c.theme))].map(t=>`<option>${E(t)}</option>`).join('')}</select></label><label>Review queue<select id="pb-status"><option value="all">All cases</option><option value="new">Unfinished cases</option><option value="review">Incorrect or revised parts</option><option value="complete">Completed cases</option></select></label><label>Search<input id="pb-search" type="search" placeholder="Concept, case or equation…"></label></div><div class="session-options"><span id="pb-count">${cases.length} cases · ${qs.length} parts</span><select id="pb-mode" aria-label="Practice or exam mode"><option value="practice">Practice · immediate explanations</option><option value="exam">Exam · explanations after finishing</option></select><select id="pb-minutes" aria-label="Session timer"><option value="0">Untimed</option><option value="40">40 minutes</option><option value="80">80 minutes</option><option value="160">160 minutes</option></select><button class="secondary" id="pb-start-all">Start all matching cases →</button></div>${s?`<div class="note"><a class="inline-link" href="#session">${s.finished?'Review':'Continue'} your saved session ↗</a> · Starting a case replaces the active session. Marked history is retained.</div>`:''}<div class="pb-grid" id="pb-cards">${cards()}</div><p class="small">Options shuffle, while parts keep their logical order. Cross out options, redo a part or redo the entire case. Every option has an explanation. Your account saves progress across devices. Export progress keeps a backup.</p>`}
 function launch(casesToStart){const ids=casesToStart.flatMap(c=>c.questionIds);if(ids.length)start(ids,'pb20',$('#pb-mode').value,Number($('#pb-minutes').value))}
 function bindCards(){document.querySelectorAll('[data-start-case]').forEach(b=>b.onclick=()=>launch([caseById[b.dataset.startCase]]))}
 function bindLobby(){bindCards();for(const key of ['theme','status','search'])$('#pb-'+key).addEventListener(key==='search'?'input':'change',e=>{filters[key]=e.target.value;const list=matching();$('#pb-cards').innerHTML=cards();$('#pb-count').textContent=`${list.length} cases · ${list.reduce((n,c)=>n+c.questionIds.length,0)} parts`;$('#pb-start-all').disabled=!list.length;bindCards()});$('#pb-start-all').onclick=()=>launch(matching())}
 function brief(q){const c=caseById[q.caseId];if(!c)return '';const s=getStore().session;return `<section class="pb-context"><p class="eyebrow">CASE ${E(c.id.slice(2))} · PART ${E(q.part)} · 8 PARTS</p><h3>${E(c.title)}</h3><details class="pb-brief" ${briefOpen?'open':''}><summary>Case brief and model assumptions</summary><p class="pb-news">${E(c.context)}</p><div class="pb-source-links">${sourceLinks(c)}</div><div class="translation-tools">${translationLinks(c.context+'\n\n'+c.scenario.join('\n\n'),'Translate case brief · 中文')}</div><h4>Hypothetical teaching scenario</h4><ol>${c.scenario.map(x=>`<li>${E(x)}</li>`).join('')}</ol><p class="small">Use the stage specified in the part below. The model parameters are supplied for learning and are not estimates of real people, firms or policies.</p></details><div class="pb-parts" aria-label="Parts in this case">${c.questionIds.map(id=>{const index=s.ids.indexOf(id),active=id===q.id;return index>=0?`<button data-pb-index="${index}" class="${active?'active':''}" aria-current="${active?'step':'false'}" aria-label="Case ${E(c.id.slice(2))}, part ${E(byId[id].part)}">${E(byId[id].part)}</button>`:`<span aria-label="Part ${E(byId[id].part)} is outside this practice set">${E(byId[id].part)}</span>`}).join('')}<button class="quiet" id="redo-case">↻ Restart all eight parts</button></div></section>`}
 function bindBrief(q,save,render){const c=caseById[q.caseId];if(!c)return;$('.pb-brief')?.addEventListener('toggle',e=>{briefOpen=e.target.open});document.querySelectorAll('[data-pb-index]').forEach(b=>b.onclick=()=>{getStore().session.index=Number(b.dataset.pbIndex);save();render(false)});$('#redo-case').onclick=()=>start([...c.questionIds],'pb20')}
 return {lobby,bindLobby,brief,bindBrief};
}
